const crypto = require('crypto');

const headers = $input.first().json.headers || {};
const body = $input.first().json.body || {};

const signatureHeader = headers['x-rax-signature'];
const timestampHeader = headers['x-rax-timestamp'];
const rawBodyStr = JSON.stringify(body);

// 1. Verificación de seguridad HMAC estricta
const secret = $env.RAX_N8N_SHARED_SECRET || 'test-shared-secret-rax-n8n';
const hmac = crypto.createHmac('sha256', secret);
const expectedSig = 'sha256=' + hmac.update(`${timestampHeader}.${rawBodyStr}`).digest('hex');

if (signatureHeader !== expectedSig) {
  return [{
    json: {
      authorized: false,
      error: 'Invalid HMAC signature'
    }
  }];
}

// 2. Comprobar rol administrativo o de servicio
if (body.actor?.role !== 'admin' && body.actor?.role !== 'system') {
  return [{
    json: {
      authorized: false,
      error: 'Reprocessing requires admin or system role'
    }
  }];
}

const originalEvent = body.originalEvent || {};
const originalCorrelationId = originalEvent.correlationId || body.correlationId;
const reprocessCorrelationId = `${originalCorrelationId}_re_${Date.now()}`;

return [{
  json: {
    authorized: true,
    reprocessCorrelationId,
    originalCorrelationId,
    targetWorkflow: body.targetWorkflow,
    reprocessReason: body.reason || 'manual_admin_retry',
    event: {
      ...originalEvent,
      correlationId: reprocessCorrelationId,
      reprocessingOf: originalCorrelationId
    }
  }
}];
